import{_ as t,c as a,o as r,ae as o}from"./chunks/framework.CliRSA9F.js";const n="/images/pulse.webp",g=JSON.parse('{"title":"Pulse","description":"","frontmatter":{},"headers":[],"relativePath":"features/pulse.md","filePath":"features/pulse.md"}'),s={name:"features/pulse.md"};function i(l,e,h,d,c,u){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="pulse" tabindex="-1">Pulse <a class="header-anchor" href="#pulse" aria-label="Permalink to &quot;Pulse&quot;">​</a></h1><h2 id="discover-trending-topics-for-your-podcast" tabindex="-1">Discover Trending Topics for Your Podcast <a class="header-anchor" href="#discover-trending-topics-for-your-podcast" aria-label="Permalink to &quot;Discover Trending Topics for Your Podcast&quot;">​</a></h2><p>Pulse surfaces news, trending searches, and spikes in public interest that are relevant to your podcast&#39;s niche. Instead of manually scanning news feeds and search trends, Pulse brings the most relevant conversations directly to you — with context about why they matter for your show.</p><p><img src="'+n+'" alt="Pulse Dashboard" width="600px" style="display:block;margin:0 auto;"></p><p><strong>To access</strong>: Click <strong>Command Center</strong> in the sidebar, then open the <strong>Pulse</strong> tab.</p><h2 id="what-pulse-tracks" tabindex="-1"><strong>What Pulse Tracks</strong> <a class="header-anchor" href="#what-pulse-tracks" aria-label="Permalink to &quot;**What Pulse Tracks**&quot;">​</a></h2><p>Pulse monitors multiple signals to identify trends relevant to your podcast:</p><ul><li><strong>News coverage</strong> — Articles and stories related to your podcast&#39;s topics and keywords</li><li><strong>Trending searches</strong> — Google Trends search terms that are trending right now and match your tracked keywords</li><li><strong>Wikipedia spikes</strong> — Sudden increases in public interest for specific topics, often indicating breaking events or viral moments</li></ul><h2 id="how-trends-are-matched-to-your-podcast" tabindex="-1"><strong>How Trends Are Matched to Your Podcast</strong> <a class="header-anchor" href="#how-trends-are-matched-to-your-podcast" aria-label="Permalink to &quot;**How Trends Are Matched to Your Podcast**&quot;">​</a></h2><p>Pulse doesn&#39;t show generic trending topics. It uses your podcast&#39;s profile — including your positioning, keywords, category, and recent episode topics — to filter and rank what it finds by relevance to your specific show.</p><h2 id="what-you-ll-see-on-the-page" tabindex="-1"><strong>What You&#39;ll See on the Page</strong> <a class="header-anchor" href="#what-you-ll-see-on-the-page" aria-label="Permalink to &quot;**What You&#39;ll See on the Page**&quot;">​</a></h2><h3 id="live-niche-radar" tabindex="-1"><strong>Live Niche Radar</strong> <a class="header-anchor" href="#live-niche-radar" aria-label="Permalink to &quot;**Live Niche Radar**&quot;">​</a></h3><p>At the top, the <strong>Live niche radar</strong> (&quot;What&#39;s happening in your space&quot;) presents a set of numbered <strong>Angles</strong> — ready-made story ideas drawn from what&#39;s happening in your niche. Each angle includes a <strong>Why this matters</strong> explanation connecting it to your show and audience, plus links to the sources behind it so you can read further.</p><h3 id="news-matches" tabindex="-1"><strong>News Matches</strong> <a class="header-anchor" href="#news-matches" aria-label="Permalink to &quot;**News Matches**&quot;">​</a></h3><p>Below the radar, news articles matched to your topics appear as cards. Each card shows the source, how recently it was published, and a <strong>Signal</strong> strength indicator. When several outlets cover the same story, the card shows how many sources are reporting it — a sign the story is gaining momentum.</p><p>Use the <strong>Relevance</strong> slider to control how closely articles must match your podcast. Slide toward higher relevance to see only the tightest matches, or lower it to explore a broader set of stories.</p><h3 id="trending-keywords" tabindex="-1"><strong>Trending Keywords</strong> <a class="header-anchor" href="#trending-keywords" aria-label="Permalink to &quot;**Trending Keywords**&quot;">​</a></h3><p>The <strong>Trending keywords</strong> panel lists Google search terms trending right now that match your tracked keywords, along with recent search volume. If your podcast already ranks for one of these terms, it&#39;s marked <strong>You rank for this</strong> — a strong cue that a timely episode could capitalize on the surge.</p><h3 id="recent-wikipedia-spikes" tabindex="-1"><strong>Recent Wikipedia Spikes</strong> <a class="header-anchor" href="#recent-wikipedia-spikes" aria-label="Permalink to &quot;**Recent Wikipedia Spikes**&quot;">​</a></h3><p>The <strong>Recent Wikipedia spikes</strong> panel highlights Wikipedia articles related to your niche whose daily views have suddenly jumped. These often signal breaking news or a wave of public curiosity about a topic.</p><h2 id="using-pulse-strategically" tabindex="-1"><strong>Using Pulse Strategically</strong> <a class="header-anchor" href="#using-pulse-strategically" aria-label="Permalink to &quot;**Using Pulse Strategically**&quot;">​</a></h2><h3 id="timely-content-planning" tabindex="-1"><strong>Timely Content Planning</strong> <a class="header-anchor" href="#timely-content-planning" aria-label="Permalink to &quot;**Timely Content Planning**&quot;">​</a></h3><p>Check Pulse before your planning sessions to identify topics your audience is actively interested in. Timely episodes that tap into current conversations tend to attract new listeners through search.</p><h3 id="competitive-advantage" tabindex="-1"><strong>Competitive Advantage</strong> <a class="header-anchor" href="#competitive-advantage" aria-label="Permalink to &quot;**Competitive Advantage**&quot;">​</a></h3><p>Being among the first podcasters in your niche to cover a trending topic can boost your visibility. Pulse helps you spot opportunities before they become widely covered.</p><h3 id="content-pipeline" tabindex="-1"><strong>Content Pipeline</strong> <a class="header-anchor" href="#content-pipeline" aria-label="Permalink to &quot;**Content Pipeline**&quot;">​</a></h3><p>When you find a relevant trend, open the <a href="/features/planner.html">Planner</a> and add it as an episode idea on your Board, using the angle and sources from Pulse in your notes.</p><h2 id="integration-with-other-features" tabindex="-1"><strong>Integration with Other Features</strong> <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;**Integration with Other Features**&quot;">​</a></h2><ul><li><strong><a href="/features/planner.html">Planner</a></strong> — Add the trends you want to cover as ideas on your Board</li><li><strong><a href="/features/planner.html">AI Producer</a></strong> — Pulse insights complement the AI Producer&#39;s content gap and keyword opportunity analysis</li><li><strong><a href="/features/positioning.html">Positioning Strategy</a></strong> — Your positioning helps Pulse identify the most relevant trends for your show</li></ul><h2 id="availability" tabindex="-1"><strong>Availability</strong> <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;**Availability**&quot;">​</a></h2><p>Pulse is available to users on paid plans. Trend data updates regularly throughout the day.</p><hr><h3 id="pro-tips" tabindex="-1"><strong>Pro Tips</strong> <a class="header-anchor" href="#pro-tips" aria-label="Permalink to &quot;**Pro Tips**&quot;">​</a></h3><ul><li>Check Pulse at least weekly to stay aware of trends in your niche</li><li>Not every trend deserves an episode — focus on trends that align with your positioning and keyword strategy</li><li>Timely content works best when published quickly, so prioritize stories with a strong signal and many sources, and trending keywords you already rank for</li><li>Use trends as inspiration even if you don&#39;t cover them directly — they reveal what your audience is currently thinking about</li></ul><p>Pulse helps you stay ahead of the conversation in your niche, turning real-world events and trending searches into content opportunities that attract new listeners.</p>',35)])])}const y=t(s,[["render",i]]);export{g as __pageData,y as default};
